import re

ALLOWED = {"orders": {"id", "status", "total"}}

def check(sql):
    s = sql.strip().rstrip(";")
    if ";" in s:
        return "reject: multiple statements"
    m = re.fullmatch(r"select\s+(.+?)\s+from\s+(\w+)(\s+limit\s+\d+)?", s, re.I)
    if not m:
        return "reject: not a simple SELECT"
    cols, table = m.group(1), m.group(2).lower()
    if table not in ALLOWED:
        return "reject: table not allowed"
    for c in [x.strip().lower() for x in cols.split(",")]:
        if c not in ALLOWED[table]:
            return "reject: column not allowed: " + c
    if not m.group(3):
        s += " LIMIT 100"  # force a row limit
    return "ok: " + s

tests = [
    "SELECT id, total FROM orders",
    "SELECT id FROM orders; DROP TABLE orders",
    "SELECT card_number FROM orders",
    "SELECT * FROM users",
    "DELETE FROM orders",
]
for t in tests:
    print(t, "=>", check(t))
